package duckpgwire_test

import (
	"testing"
	"time"

	"github.com/egdaemon/eg/duckpgwire"
	"github.com/egdaemon/eg/internal/sqltestx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestWithStatementTimeout(t *testing.T) {
	t.Run("option is accepted by New without panic", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		srv := duckpgwire.New(db, duckpgwire.WithStatementTimeout(5*time.Second))
		require.NotNil(t, srv)
	})

	t.Run("zero duration is accepted", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		srv := duckpgwire.New(db, duckpgwire.WithStatementTimeout(0))
		require.NotNil(t, srv)
	})

	t.Run("returned option is non-nil", func(t *testing.T) {
		opt := duckpgwire.WithStatementTimeout(30 * time.Second)
		require.NotNil(t, opt)
	})
}
